import StringPiece from "../models/string_piece"

// 白名单精确允许集：文本片段一律按纯文本序列化进 HTML。
// 唯一允许原样通过的是不具备 HTML 语法功能的普通字符；
// 对文本上下文有语法意义的 & < > 双引号 单引号 全部实体转义，
// 不做任何危险标签识别，不存在可被绕过的黑名单匹配面。
const HTML_ENTITY_MAP = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
}

// 逐字符查表：命中映射表的语法字符输出实体，其余字符原样保留
const escapeHTML = (text) => {
  let safe = ""
  for (const ch of String(text)) {
    safe += HTML_ENTITY_MAP[ch] || ch
  }
  return safe
}

// 把反序列化出的片段列表合并为一个 HTML 字符串
export function buildDocumentHTML(pieceList) {
  let merged = null
  for (const item of pieceList || []) {
    const piece = StringPiece.fromJSON(item) // 触达 source
    if (merged && merged.canBeConsolidatedWith(piece)) {
      merged = merged.consolidateWith(piece) // 字符串原样拼接
    } else {
      merged = piece
    }
  }
  return escapeHTML(merged ? merged.getValue() : "") // 集中防御点：出口统一白名单转义
}

// 纯传递包装：入参已在 buildDocumentHTML 出口完成白名单转义，此处仅拼接静态 span 标签
export function wrapInline(html) {
  return `<span class="doc">${html}</span>`
}

