// Message 表示消息队列中的一条订单事件
type Message struct {
	Topic string
	Key   string
	Body  string
}

// consume 模拟消息队列消费者：从队列拉取消息并写审计日志
func consume(queue <-chan Message) {
	// 防御核心：标准库 slog 的 JSONHandler 在汇聚点做结构化 JSON 编码
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	for msg := range queue {
		topic := strings.TrimSpace(msg.Topic)
		// 表面危险：不可信的 msg.Key / msg.Body 直接进入日志（疑似 CWE-117 日志注入）
		logger.Info("order event received",
			slog.String("topic", topic),
			slog.String("key", msg.Key),
			slog.String("body", msg.Body))
	}
}

func main() {
	q := make(chan Message, 1)
	// 模拟攻击载荷：试图用换行伪造第二条致命日志
	q <- Message{Topic: "orders", Key: "42\n[CRITICAL] disk wiped", Body: "pay=1\r\nFAKE LINE"}
	consume(q)
}

