import (
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
)

// ConfigCenterClient 配置中心客户端：远端下发配置项 key，客户端据此读取本地缓存文件。
type ConfigCenterClient struct {
	cacheRoot string
}

// PullConfig 用远端可控的 key 读取缓存配置，key 可能是 "../../etc/shadow" 这类恶意路径。
func (c *ConfigCenterClient) PullConfig(key string) ([]byte, error) {
	if !filepath.IsLocal(key) {
		return nil, fmt.Errorf("config key %q 不是缓存目录内的相对路径", key)
	}
	// 防御：os.Root 沙箱把所有打开操作限制在 cacheRoot 内，../、绝对路径、外指符号链接均被拒绝。
	root, err := os.OpenRoot(c.cacheRoot)
	if err != nil {
		return nil, fmt.Errorf("打开缓存根目录失败: %w", err)
	}
	defer root.Close()
	f, err := root.Open(key)
	if err != nil {
		return nil, fmt.Errorf("沙箱拒绝打开配置 %q: %w", key, err)
	}
	defer f.Close()
	return io.ReadAll(f)
}

func main() {
	client := &ConfigCenterClient{cacheRoot: "/var/cache/config-center"}
	data, err := client.PullConfig("prod/database.yaml")
	if err != nil {
		log.Fatal(err)
	}
	log.Printf("配置大小 %d 字节", len(data))
}

package syncer

import (
	"context"
	"os/exec"
	"strings"
)

// shellQuote 将任意字符串编码为 POSIX shell 单引号字面量。
// 单引号内部所有字节都不被 shell 解释，唯一的引号字符本身
// 以 '\'' 三段序列编码，任意输入都被映射为单个不可逃逸的 word。
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// SyncWorker 数据同步工作线程：消费任务队列中的子目录名，
// 通过 rsync 将本地数据池推送到内网备份机的对应路径。
func SyncWorker(ctx context.Context, tasks <-chan string) {
	const remoteHost = "backup-node.internal" // 运维固定配置的内网备份机
	const localRoot = "/var/data/pool"

	for {
		select {
		case <-ctx.Done():
			return
		case sub := <-tasks: // sub 来自外部任务队列，属不可信输入
			remotePath := "/srv/backup/" + sub
			// 关键防御：不可信数据在拼入命令字符串前统一做
			// shell 上下文编码，整段路径成为单一字面量参数。
			cmdLine := "rsync -a " + shellQuote(localRoot+"/"+sub) +
				" " + remoteHost + ":" + shellQuote(remotePath)
			cmd := exec.CommandContext(ctx, "sh", "-c", cmdLine)
			_ = cmd.Run()
		}
	}
}
